  "selectedwork.subtitle": { en: "Representative project directions that reflect our capabilities and vision.", de: "Repräsentative Projektrichtungen, die unsere Fähigkeiten und Vision widerspiegeln.", fr: "Directions de projets représentatives qui reflètent nos capacités et notre vision.", es: "Direcciones de proyectos representativas que reflejan nuestras capacidades y visión.", it: "Direzioni di progetto rappresentative che riflettono le nostre capacità e la nostra visione.", pt: "Direções de projetos representativas que refletem nossas capacidades e visão.", nl: "Representatieve projectrichtingen die onze capaciteiten en visie weerspiegelen.", tr: "Yeteneklerimizi ve vizyonumuzu yansıtan temsili proje yönleri.", ar: "اتجاهات مشاريع تمثيلية تعكس قدراتنا ورؤيتنا.", zh: "反映我们能力和愿景的代表性项目方向。" },
  "selectedwork.ai": { en: "AI Business Systems", de: "KI-Geschäftssysteme", fr: "Systèmes d'Affaires IA", es: "Sistemas Empresariales de IA", it: "Sistemi Aziendali IA", pt: "Sistemas Empresariais de IA", nl: "AI-bedrijfssystemen", tr: "Yapay Zeka İş Sistemleri", ar: "أنظمة أعمال الذكاء الاصطناعي", zh: "AI商业系统" },
